mapper.select:
SELECT COUNT(*)
FROM orders

    user_id = #{userId}

        AND [status] = #{status}

SELECT order_id, user_id, voucher_id, order_date, [status], total_amount, discount_amount, final_amount, shipping_fee, shipping_fullname, shipping_phone, shipping_address, shipping_city, shipping_country, [note], created_at, updated_at FROM orders
user_id = #{userId}
AND [status] = #{status}
ORDER BY order_date DESC OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(*) FROM orders WHERE 1=1
AND [status] = #{status}
AND (shipping_fullname LIKE ('%' + #{searchTerm} + '%') OR shipping_phone LIKE ('%' + #{searchTerm} + '%') OR CAST(order_id AS VARCHAR) LIKE ('%' + #{searchTerm}) + '%')

SELECT COALESCE(SUM(final_amount), 0)
FROM orders
WHERE [status] = 'DELIVERED'
AND YEAR(order_date) = #{year}
AND MONTH(order_date) = #{month}
